const C={blue:'#5d7fb3',amber:'#D9B84A',red:'#E0707B',purple:'#B877D9',green:'#73BF69',text:'#e6e7e8',muted:'#9fa2a8',line:'#7fa6d9',grid:'#22252b',card:'#181b1f',border:'#2a2d33'};
const S=id=>context.panel.data.series.find(x=>x.refId===id);const col=(id,n)=>{const s=S(id);const f=s&&s.fields.find(f=>f.name===n);return f?f.values:[];};
const ist=t=>new Date(t+19800000).toISOString().slice(0,10);const todayK=ist(Date.now());const dayMs=86400000;
