const daysBetween=(a,b)=>Math.round((new Date(b)-new Date(a))/dayMs);
const rows=[];
// statistics-table sites
const A=n=>col('A',n);for(let i=0;i<A('name').length;i++){rows.push({ord:A('ord')[i],name:A('name')[i],sub:A('grp')[i],des:A('des')[i],up:A('up_to')[i],behind:A('behind')[i],flow30:A('flow30')[i],pct:A('pct')[i],series:(A('series')[i]||'').split(',').slice(0,30).map(v=>v===''?null:+v),kwh:A('kwh30')[i],m3:A('m3_30')[i],klbl:A('key_lbl')[i],kval:A('key_val')[i],kunit:A('key_unit')[i],kcol:A('key_col')[i],sok:A('score_ok')[i],sn:A('score_n')[i],slbl:'outlet COD, TSS, ammonia, pH',sev:A('sev')[i]});}
