const sensor=(id,name,sub,des,minN,ord,extra)=>{const T=col(id,'Time'),M=col(id,'m3'),K=col(id,'kwh'),N=col(id,'n'),R=col(id,'rec');const by={};
 for(let i=0;i<T.length;i++){const k=ist(T[i]);if(k===todayK)continue;if(M[i]==null||(N.length&&N[i]<minN)||M[i]<=0)continue;by[k]={m3:M[i],kwh:K[i],rec:R.length?R[i]:null};}
 const ks=keys.filter(k=>by[k]);const up=ks.length?ks[ks.length-1]:null;const ser=keys.map(k=>by[k]?by[k].m3:null);
 const v=ks.map(k=>by[k]);const flow30=v.length?v.reduce((a,b)=>a+b.m3,0)/v.length:null;const ev=v.filter(x=>x.kwh>0&&x.m3>20);
 const r={ord,name,sub,des,up:fmtD(up),behind:up?daysBetween(up,yK):null,flow30,pct:up?by[up].m3/des*100:null,series:ser,kwh:ev.reduce((a,b)=>a+b.kwh,0),m3:ev.reduce((a,b)=>a+b.m3,0),days:v};
