const lab=n=>{const N=col('L','name'),V=col('L','v');const i=N.indexOf(n);return i<0?null:V[i];};
const n24=id=>{const v=col(id,'n24');return v.length?v[0]:0;};
const stale=(id,h)=>lastAge(id)>h;
const sevOf=(r,purple,amber)=>(r.up==null||r.behind>3||purple)?'purple':((r.behind>1||r.flow30>r.des||amber)?'amber':'ok');
rows.push(sensor('D','Zim Lab','ZLD · 250 m³/d inlet',250,0,1,r=>{const rec=r.days.filter(x=>x.rec!=null);const avg=rec.length?rec.reduce((a,b)=>a+b.rec,0)/rec.length:null;
 return {klbl:'RO recovery',kval:avg,kunit:'%',kcol:avg==null?'none':(avg>=98?'ok':'amber'),sok:rec.filter(x=>x.rec>=98).length,sn:rec.length,slbl:'RO recovery ≥ 98 %',noAvgE:true,sev:sevOf(r,stale('J',12),(avg!=null&&avg<98)||n24('H')<130)};}));
rows.push(sensor('B','Riverview 1500','MBR · 1,500 m³/d',1500,38,5,r=>({klbl:'Treated COD (lab)',kval:lab('Riverview 1500'),kunit:'mg/L',kcol:'none',sok:null,sn:null,slbl:'no limits set',sev:sevOf(r,stale('F',12),n24('E')<130)})));
