const ew=rows.filter(r=>!r.noAvgE&&r.m3>0);const seW=ew.reduce((a,b)=>a+b.kwh,0)/ew.reduce((a,b)=>a+b.m3,0);
const tiles=[['Data current',cur+' of '+rows.length,cur===rows.length?C.green:C.amber,'readings up to yesterday or today'],['Need attention',att+' of '+rows.length,alm?C.red:(att?C.amber:C.green),(alm?alm+' alarm · ':'')+'see the dots below'],['Output vs design',avgP==null?'—':Math.round(avgP)+' %',C.text,'average of sites'],['Specific energy ⌀',isFinite(seW)?seW.toFixed(2)+' kWh/m³':'—',C.text,'flow-weighted · excl. Zim Lab (per m³ inlet)']];
const tw=(W-30)/4;tiles.forEach((t,i)=>{const x=i*(tw+10);g.push({type:'rect',shape:{x,y:0,width:tw,height:82,r:4},style:{fill:C.card,stroke:C.border}});
 g.push({type:'text',left:x+14,top:10,style:{text:t[0],fill:C.muted,fontSize:12}});g.push({type:'text',left:x+14,top:28,style:{text:t[1],fill:t[2],fontSize:24,fontWeight:600}});g.push({type:'text',left:x+14,top:60,style:{text:t[3],fill:C.muted,fontSize:11}});});
const top0=96,head=26,rowH=Math.max(34,(H-top0-head-4)/rows.length);
const X={name:0.01,up:0.17,flow:0.24,trend:0.45,se:0.62,key:0.71,score:0.83};
[['Site','name'],['Data up to','up'],['Output ⌀ 30 d · % of design','flow'],['Trend · 30 days','trend'],['kWh/m³ ⌀ (0–2.5)','se'],['Key metric ⌀ 30 d','key'],['Within limits · 30 d','score']].forEach(([t,k])=>g.push({type:'text',left:X[k]*100+'%',top:top0+6,style:{text:t,fill:C.muted,fontSize:12}}));
g.push({type:'rect',shape:{x:0,y:top0+head-2,width:W,height:1},style:{fill:C.border}});
const sevC={ok:C.green,amber:C.amber,purple:C.purple,red:C.red};const f0=v=>v==null?'—':Math.round(v).toLocaleString('en-US');
rows.forEach((r,i)=>{const y=top0+head+i*rowH,cy=y+rowH/2;
 g.push({type:'circle',shape:{cx:W*X.name+5,cy,r:5},style:{fill:sevC[r.sev]||C.green}});
 g.push({type:'text',left:W*X.name+16,top:cy-15,style:{text:r.name,fill:C.text,fontSize:13,fontWeight:600}});g.push({type:'text',left:W*X.name+16,top:cy+2,style:{text:r.sub,fill:C.muted,fontSize:11}});
 g.push({type:'text',left:X.up*100+'%',top:cy-7,style:{text:r.up||'no data',fill:(r.up==null||r.behind>3)?C.purple:(r.behind>1?C.amber:C.text),fontSize:13}});
 if(r.flow30!=null){const p=r.pct==null?null:Math.round(r.pct);const x0=W*X.flow,w=W*(X.trend-X.flow)-24;
  g.push({type:'text',left:x0,top:cy-16,style:{text:f0(r.flow30)+' m³'+(r.name==='Zim Lab'?' inlet':''),fill:C.text,fontSize:13}});
  g.push({type:'text',left:x0+w-40,top:cy-16,style:{text:p==null?'—':p+' %',fill:p>100?C.amber:C.text,fontSize:13,fontWeight:500}});
  g.push({type:'rect',shape:{x:x0,y:cy+4,width:w,height:7,r:3},style:{fill:'#2a2d33'}});if(p!=null)g.push({type:'rect',shape:{x:x0,y:cy+4,width:w*Math.min(p,150)/150,height:7,r:3},style:{fill:p>100?C.amber:C.blue}});
  g.push({type:'rect',shape:{x:x0+w*100/150-1,y:cy+1,width:2,height:13},style:{fill:C.text}});} else g.push({type:'text',left:X.flow*100+'%',top:cy-7,style:{text:'no data',fill:C.muted,fontSize:13}});
 const vals=r.series;grids.push({left:X.trend*100+'%',width:(X.se-X.trend-0.02)*100+'%',top:y+6,height:rowH-12});xa.push({type:'category',gridIndex:i,show:false,data:vals.map((_,k)=>k)});
