 ser.push({type:'line',xAxisIndex:i,yAxisIndex:i,data:vals,connectNulls:false,symbol:'none',showSymbol:false,lineStyle:{color:C.line,width:1.5},silent:true,markLine:{symbol:'none',silent:true,label:{show:false},lineStyle:{type:'dashed',color:'#6c6f75',width:1},data:[{yAxis:r.des}]}});
