 else g.push({type:'text',left:sx,top:cy-7,style:{text:'—',fill:C.muted,fontSize:13}});
 g.push({type:'text',left:X.key*100+'%',top:cy-15,style:{text:r.klbl,fill:C.muted,fontSize:11}});
